mapper.select:
SELECT * FROM ( SELECT SNAPSHOT_NO AS snapshotNo, ITEM_CODE AS itemCode, ITEM_NAME AS itemName, MARKET_TYPE AS marketType, UNIT AS unit, AVG_PRICE AS avgPrice, MIN_PRICE AS minPrice, MAX_PRICE AS maxPrice, CHANGE_RATE AS changeRate, TO_CHAR(SNAPSHOT_DATE, 'YYYY-MM-DD') AS snapshotDate, SOURCE_NAME AS sourceName FROM OFT_PRICE_SNAPSHOT WHERE 1 = 1
AND SNAPSHOT_DATE = TO_DATE(#{snapshotDate}, 'YYYY-MM-DD')
AND MARKET_TYPE = #{marketType}
AND UPPER(ITEM_NAME) LIKE '%' || UPPER(#{itemName}) || '%'
ORDER BY SNAPSHOT_DATE DESC, MARKET_TYPE ASC, ITEM_NAME ASC ) WHERE ROWNUM <= #{limit}
